import sys, base64, zlib, json
def dec(s):
    s=s.strip(); pad='='*(-len(s)%4)
    return zlib.decompress(base64.urlsafe_b64decode(s+pad)).decode()
txt=sys.stdin.read()
# assume json shell output
try:
    d=json.loads(txt)
except Exception:
    print("NOT-JSON:", repr(txt)); sys.exit(0)
for k,v in d.items():
    if k=="DIRENV_WATCHES":
        print(json.dumps(json.loads(dec(v)), indent=1))
    else:
        print(k,"=",repr(v))
EOF
